<template>
  <AppHeader />
  <main class="music-assistant" data-route-motion-root>
    <header class="ma-heading">
      <div class="ma-heading-copy"><span class="ma-breadcrumb">灵感工作室</span><h1>AI 选歌<span>音乐，懂你多一点。</span></h1></div>
      <span class="ma-provider" :class="{'is-connected':connected}"><span class="ma-status-dot" />{{ connected ? '网易云音乐已连接' : '由你的音乐灵感开启' }}</span>
    </header>

    <MaintenanceFeature target="feature.musicAssistant">
      <div class="ma-layout">
        <aside class="ma-sidebar" aria-label="音乐助手工具">
          <div class="ma-sidebar-brand"><span class="ma-brand-mark"><AppIcon name="audio-lines" :size="23" /></span><div><h2>音乐灵感</h2><p>为此刻，找一首歌。</p></div></div>
          <button class="ma-new-chat" :disabled="state.busy || !state.messages.length" @click="newConversation"><AppIcon name="square-pen" :size="17" />开启新对话<AppIcon name="plus" :size="15" /></button>
          <section class="ma-shortcuts"><h3>从一个念头开始</h3><button v-for="prompt in prompts" :key="prompt.label" :disabled="state.busy" @click="choosePrompt(prompt.text)"><AppIcon :name="prompt.icon" :size="18" /><span>{{ prompt.label }}</span><AppIcon name="arrow-up-right" :size="14" /></button></section>
          <div class="ma-sidebar-bottom">
            <section class="ma-account" aria-label="官方音乐账号连接">
              <div class="ma-account-heading"><span class="ma-account-icon"><AppIcon :name="connected ? 'circle-check' : 'headphones'" :size="20" /></span><div><strong>{{ connected ? '音乐账号已连接' : '连接你的音乐' }}</strong><p>{{ connected ? '开始你的音乐对话' : state.connection.status === 'PENDING' ? '请在网易云音乐确认' : '找到更懂你的声音' }}</p></div><span v-if="connected" class="ma-status-dot" /></div>
              <button v-if="!connected" class="ma-connect" :disabled="state.loading || state.connecting || !state.capabilities.musicConfigured" @click="state.connection.status === 'PENDING' ? authorizationOpen = true : connect()"><AppIcon :name="state.connecting ? 'loader-circle' : 'link'" :class="{'ma-spin':state.connecting}" :size="16" />{{ state.connecting ? '正在连接…' : state.connection.status === 'PENDING' ? '继续官方授权' : '连接网易云音乐' }}<AppIcon name="arrow-up-right" :size="15" /></button>
              <button v-else class="ma-disconnect" :disabled="state.saving" @click="disconnect"><AppIcon name="unlink" :size="14" />断开连接</button>
            </section>
            <p class="ma-privacy"><AppIcon name="shield-check" :size="15" /><span>通过网易云官方授权连接。音乐需求与必要的歌曲信息将用于 AI 推荐。</span></p>
          </div>
        </aside>

        <section class="ma-conversation" :class="{'is-empty':!state.messages.length}" aria-label="音乐助手对话">
          <header class="ma-chat-top"><div><span class="ma-chat-mark"><AppIcon name="sparkles" :size="17" /></span><strong>你的音乐对话</strong><span class="ma-chat-label">一起找点好听的</span></div><button class="ma-text-button ma-reset" :disabled="state.busy || !state.messages.length" @click="newConversation"><AppIcon name="plus" :size="16" />新对话</button></header>
          <div v-if="state.error" class="ma-error" role="alert"><AppIcon name="circle-alert" :size="17" /><span>{{ state.error }}</span><button aria-label="关闭提示" @click="state.error=''"><AppIcon name="x" :size="16" /></button></div>
          <div v-if="state.notice" class="ma-confirmation" role="status"><AppIcon name="circle-check" :size="16" />{{ state.notice }}</div>
          <div v-if="!state.loading && (!state.capabilities.musicConfigured || !state.capabilities.modelConfigured)" class="ma-notice" role="status"><AppIcon name="info" :size="17" />{{ !state.capabilities.musicConfigured ? '音乐授权服务暂未就绪，请稍后再试。' : 'AI 服务暂未就绪，请稍后再试。' }}</div>

          <div ref="conversationRef" class="ma-transcript" aria-live="polite" aria-relevant="additions text" :aria-busy="state.busy">
            <div v-if="!state.messages.length" class="ma-welcome">
              <span class="ma-welcome-symbol"><AppIcon name="audio-lines" :size="30" /></span>
              <p class="ma-welcome-caption">每一种心情，都有它的旋律</p>
              <h2>今天，想听点什么？</h2>
              <p>聊聊此刻的心情，或说一位喜欢的艺人。<br />剩下的，我们一起慢慢找。</p>
              <div class="ma-prompts"><button v-for="prompt in prompts" :key="prompt.label" :disabled="state.busy" @click="choosePrompt(prompt.text)"><span class="ma-prompt-icon"><AppIcon :name="prompt.icon" :size="20" /></span><strong>{{ prompt.label }}</strong><small>{{ prompt.description }}</small><AppIcon class="ma-prompt-arrow" name="arrow-up-right" :size="15" /></button></div>
            </div>
            <div v-else class="ma-messages">
              <article v-for="message in state.messages" :key="message.id" class="ma-message" :class="'is-'+message.role">
                <span v-if="message.role !== 'user'" class="ma-message-avatar" aria-label="音乐助手"><AppIcon name="audio-lines" :size="18" /></span>
                <div class="ma-message-body"><span v-if="message.role !== 'user'" class="ma-message-role">Aurora 音乐助手</span><p class="ma-message-copy">{{ message.content }}</p>
                  <template v-if="message.tracks?.length">
                    <div class="ma-tracks"><article v-for="(track,index) in message.tracks" :key="track.id" class="ma-track"><button class="ma-track-cover" :aria-label="'播放'+track.name" :disabled="state.playing" @click="play([track])"><img v-if="track.cover" :src="track.cover" alt="" loading="lazy" referrerpolicy="no-referrer" /><AppIcon v-else name="music" :size="22" /><span class="ma-track-hover"><AppIcon name="play" :size="18" filled /></span></button><div class="ma-track-copy"><small>{{ String(index+1).padStart(2,'0') }}</small><h3>{{ track.name }}</h3><p>{{ track.artists?.join(' / ') || '未知艺人' }}</p><span v-if="track.reason">{{ track.reason }}</span></div><button class="ma-track-add" :disabled="state.playing" :aria-label="'将'+track.name+'加入队列'" @click="queue([track])"><AppIcon name="plus" :size="17" /></button></article></div>
                    <div class="ma-result-actions"><button class="ma-play" :disabled="state.playing" @click="play(message.tracks)"><AppIcon :name="state.playing ? 'loader-circle' : 'play'" :class="{'ma-spin':state.playing}" :size="15" />{{ state.playing ? '正在准备…' : '播放这些歌' }}</button><button :disabled="state.playing" @click="queue(message.tracks)"><AppIcon name="list-plus" :size="16" />加入队列</button><button v-if="state.connection.canSavePlaylist" :disabled="state.saving" @click="beginSave(message)"><AppIcon name="list-music" :size="16" />保存为歌单</button></div>
                    <form v-if="state.saveMessage===message.id" class="ma-save-form" @submit.prevent="save(message)"><label :for="'ma-save-'+message.id">歌单名称</label><input :id="'ma-save-'+message.id" v-model="state.playlistName" maxlength="80" required :disabled="state.saving" /><button class="ma-play" :disabled="state.saving || !state.playlistName.trim()"><AppIcon :name="state.saving ? 'loader-circle' : 'check'" :size="15" />{{ state.saving ? '正在保存…' : '创建并保存' }}</button><button type="button" :disabled="state.saving" @click="state.saveMessage=''">取消</button></form>
                  </template>
                  <div v-if="message.playlist" class="ma-saved"><span><AppIcon name="circle-check" :size="16" />已保存 {{ message.playlist.count }} 首歌曲</span><a :href="message.playlist.url" target="_blank" rel="noopener noreferrer">打开「{{ message.playlist.name }}」<AppIcon name="arrow-up-right" :size="14" /></a></div>
                </div>
              </article>
              <div v-if="state.busy" class="ma-working" role="status"><span class="ma-message-avatar"><AppIcon name="audio-lines" :size="18" /></span><span class="ma-working-dots"><i /><i /><i /></span><span>{{ state.stage || '正在寻找适合你的声音' }}</span><button class="ma-text-button" @click="cancel">停止</button></div>
            </div>
          </div>

          <div class="ma-composer-wrap"><form class="ma-composer" @submit.prevent="state.busy ? cancel() : send()"><label class="ma-sr-only" for="ma-input">告诉音乐助手你想听什么</label><textarea id="ma-input" ref="inputRef" v-model="state.input" rows="2" maxlength="1500" :disabled="state.loading" placeholder="想听什么？一句话就好…" @keydown.enter.exact.prevent="send" /><div class="ma-composer-bottom"><span><AppIcon :name="connected ? 'music' : 'link'" :size="14" />{{ connected ? '已连接你的音乐空间' : '连接账号后，即可开始对话' }}</span><button type="submit" class="ma-send" :disabled="!state.busy && !canSend" :aria-label="state.busy ? '停止生成' : '发送音乐需求'"><AppIcon :name="state.busy ? 'square' : 'arrow-up'" :size="21" /></button></div></form><p class="ma-input-hint"><span>Enter 发送<span class="ma-hint-separator">·</span>Shift + Enter 换行</span><span>好音乐，来自真实搜索</span></p></div>
        </section>
      </div>
    </MaintenanceFeature>
  </main>

  <!-- Dialog is portaled to body; its root needs an unscoped overlay layer. -->
  <Dialog :open="authorizationOpen && state.connection.status==='PENDING'" class="ma-auth-dialog" @close="authorizationOpen=false">
    <div class="ma-auth-backdrop" aria-hidden="true" />
    <div class="ma-auth-position"><DialogPanel class="ma-auth-panel"><button class="ma-auth-close" aria-label="关闭授权窗口" @click="authorizationOpen=false"><AppIcon name="x" :size="20" /></button><span class="ma-auth-mark"><AppIcon name="headphones" :size="27" /></span><DialogTitle>连接你的网易云音乐</DialogTitle><p>用网易云音乐扫码，在官方页面确认授权。</p><div class="ma-qr"><QRCode :value="state.connection.authorizeUrl || 'https://music.163.com'" :size="180" :bordered="false" /></div><span class="ma-auth-waiting"><span class="ma-status-dot" />等待你在网易云音乐中确认</span><a class="ma-connect" :href="state.connection.authorizeUrl" target="_blank" rel="noopener noreferrer">打开官方授权页面<AppIcon name="arrow-up-right" :size="16" /></a><div class="ma-auth-actions"><button class="ma-text-button" :disabled="state.connecting" @click="connect"><AppIcon name="refresh-cw" :size="14" />重新获取</button><button class="ma-text-button" :disabled="state.connecting" @click="disconnect">取消连接</button></div><p class="ma-auth-privacy"><AppIcon name="shield-check" :size="14" />凭证仅保留在服务端</p></DialogPanel></div>
  </Dialog>
</template>


<script setup>
import AppIcon from "@/components/icons/AppIcon.vue"
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue'
import {QRCode} from 'ant-design-vue'
import {Dialog,DialogPanel,DialogTitle} from '@headlessui/vue'
import AppHeader from '@/components/appHeader/AppHeader.vue'
import MaintenanceFeature from '@/components/maintenance/MaintenanceFeature.vue'
import {musicAssistantConnection} from '@/composables/musicAssistantConnection.js'
import {useCounterStore} from '@/stores/userStores.js'
import {usePlayerStore} from '@/stores/playerStore.js'
import {useMaintenanceAccess} from '@/composables/useMaintenanceAccess.js'
import {isTargetAvailable,requireFeature} from '@/utils/maintenanceAccess.js'
import {playSongWithQueue} from '@/utils/globalPlayer.js'

const user=useCounterStore(),player=usePlayerStore(),maintenance=useMaintenanceAccess(),conversationRef=ref(null),inputRef=ref(null)
const state=reactive({loading:true,connecting:false,saving:false,playing:false,busy:false,input:'',error:'',notice:'',stage:'',messages:[],connection:{status:'DISCONNECTED',authorizeUrl:'',message:'',canSavePlaylist:false},capabilities:{musicConfigured:false,modelConfigured:false},saveMessage:'',playlistName:''})
const authorizationOpen=ref(false)
watch(()=>state.connection.status,status=>{authorizationOpen.value=status==='PENDING'})
const connected=computed(()=>state.connection.status==='CONNECTED')
const available=computed(()=>['page.musicAssistant','feature.musicAssistant','feature.ai'].every(key=>isTargetAvailable(maintenance.value.settings,key)))
const canSend=computed(()=>available.value&&connected.value&&state.capabilities.modelConfigured&&!state.busy&&!!state.input.trim())
const api=musicAssistantConnection(user)
const prompts=[{icon:'moon',label:'深夜，慢一点',description:'安静但不沉闷',text:'推荐一些适合晚上安静听的歌曲，不要太悲伤。'},{icon:'compass',label:'听点新鲜的',description:'发现不一样的声音',text:'帮我找一些不太常见、但旋律好听的独立流行歌曲。'},{icon:'heart',label:'从喜欢出发',description:'沿着收藏继续发现',text:'如果可以读取我的红心歌曲，请根据收藏推荐一些新的歌曲，并说明推荐依据。'}]
let active=true,authTimer=0,jobTimer=0,noticeTimer=0,jobId='',requestController=new AbortController()
function assertActive(){if(!active||!available.value)throw new DOMException('操作已取消','AbortError')}
function fail(error){if(error.name==='AbortError'||!active)return;state.error=error.message||'音乐助手暂时不可用';if(error.status===401)state.connection={status:'DISCONNECTED',message:'授权已过期，请重新连接'}}
function scrollBottom(){void nextTick(()=>{const element=conversationRef.value;if(element)element.scrollTop=element.scrollHeight})}
async function refreshConnection(){
  try{const value=await api.connection({signal:requestController.signal});assertActive();state.connection=value;if(value.status==='PENDING')authTimer=setTimeout(refreshConnection,5000)}catch(error){fail(error);if(error.status!==429&&active&&available.value&&state.connection.status==='PENDING'&&state.connection.expiresAt>Date.now())authTimer=setTimeout(refreshConnection,8000)}
}
async function connect(){if(!available.value||state.connecting)return;state.connecting=true;state.error='';clearTimeout(authTimer);state.connection={status:'DISCONNECTED',message:'正在准备官方授权…'};state.messages=[];state.saveMessage='';try{await api.reset();assertActive();const value=await api.connect({signal:requestController.signal});assertActive();state.connection=value;if(value.status==='PENDING')authTimer=setTimeout(refreshConnection,4000)}catch(error){fail(error)}finally{state.connecting=false}}
async function disconnect(){clearTimeout(authTimer);clearTimeout(jobTimer);await cancel();requestController.abort();requestController=new AbortController();state.connection={status:'DISCONNECTED',message:''};state.messages=[];state.error='';state.saveMessage='';void api.reset()}
function choosePrompt(text){state.input=text;inputRef.value?.focus()}
async function newConversation(){if(!available.value||state.busy)return;try{await api.clear({signal:requestController.signal});assertActive();state.messages=[];state.error='';state.saveMessage=''}catch(error){fail(error)}}
async function send(){
  if(!canSend.value)return;const content=state.input.trim();state.input='';state.error='';state.busy=true;state.stage='理解你的需求';state.messages.push({id:crypto.randomUUID(),role:'user',content});scrollBottom()
  try{const work=await api.send(content,{signal:requestController.signal});assertActive();jobId=work.id;await pollJob()}catch(error){fail(error);state.busy=false}
}
async function pollJob(){
  const id=jobId
  try{const work=await api.job(id,{signal:requestController.signal});assertActive();if(id!==jobId)return;state.stage=work.stage;scrollBottom();if(work.status==='RUNNING'){jobTimer=setTimeout(pollJob,1000);return}state.busy=false;jobId='';if(work.status==='COMPLETED')state.messages.push({id:work.id,role:'assistant',content:work.message,tracks:work.tracks});else if(work.status==='FAILED')state.error=work.message;scrollBottom()}catch(error){fail(error);state.busy=false}
}
async function cancel(){clearTimeout(jobTimer);const id=jobId;jobId='';state.busy=false;if(id)await api.cancel(id).catch(()=>{})}
function trackForPlayer(track){return {id:track.id,name:track.name,artists:(track.artists||[]).map(name=>({name})),album:{name:track.album},cover:track.cover,dt:track.durationMs}}
async function play(tracks){if(!available.value||!requireFeature('feature.playback')||state.playing)return;state.playing=true;try{const queue=tracks.map(trackForPlayer);await playSongWithQueue(queue[0],queue,0,{maintenanceTargets:['page.musicAssistant','feature.musicAssistant','feature.ai']});assertActive()}catch(error){fail(error)}finally{state.playing=false}}
function queue(tracks){if(!available.value||!requireFeature('feature.playback'))return;player.setQueue([...(player.playQueue||[]),...tracks.map(trackForPlayer)],{startIndex:Math.max(0,player.currentQueueIndex||0)});state.notice=`已将 ${tracks.length} 首歌曲加入播放队列`;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>{state.notice=''},3500)}
function beginSave(message){if(!available.value)return;state.saveMessage=message.id;state.playlistName='Aurora · 此刻想听'}
async function save(message){if(!available.value||state.saving||!state.playlistName.trim())return;state.saving=true;state.error='';try{const result=await api.save(state.playlistName.trim(),message.tracks.map(track=>track.id),{signal:requestController.signal});assertActive();message.playlist=result;state.saveMessage=''}catch(error){fail(error)}finally{state.saving=false}}
watch(available,value=>{if(!value)void disconnect()})
watch(()=>[user.isLoggedIn,user.userId],()=>{void disconnect()})
onMounted(async()=>{try{state.capabilities=await api.capabilities();assertActive();await refreshConnection();if(connected.value){const saved=await api.conversation({signal:requestController.signal});assertActive();state.messages=saved.messages||[];scrollBottom()}}catch(error){fail(error)}finally{state.loading=false}})
onBeforeUnmount(()=>{active=false;clearTimeout(authTimer);clearTimeout(jobTimer);clearTimeout(noticeTimer);if(jobId)void api.cancel(jobId).catch(()=>{});requestController.abort()})
</script>

<style scoped>
.music-assistant{--ma-ink:#282c2a;--ma-muted:#777e78;--ma-line:#e7e9e3;--ma-accent:#e58271;box-sizing:border-box;display:flex;flex-direction:column;gap:20px;height:calc(100dvh - 68px - var(--global-player-space,110px) - 24px);min-height:490px;padding:23px clamp(20px,3.3vw,56px) 0;background:#f7f8f5;color:var(--ma-ink)}
.ma-heading{display:flex;flex:none;align-items:center;justify-content:space-between;gap:20px;width:100%;max-width:1540px;margin:0 auto}.ma-breadcrumb{display:block;margin-bottom:5px;color:#8b928b;font-size:12px;letter-spacing:.08em}.ma-heading h1{display:flex;align-items:center;gap:17px;margin:0;font-size:24px;font-weight:750;letter-spacing:-.045em;line-height:1.25}.ma-heading h1>span{padding-left:17px;border-left:1px solid #dfe2dc;color:#8b928b;font-size:12px;font-weight:400;letter-spacing:0}.ma-provider{display:flex;align-items:center;gap:7px;color:#92988f;font-size:12px;white-space:nowrap}.ma-provider.is-connected{color:#617a69}.ma-status-dot{display:inline-block;width:6px;height:6px;flex-shrink:0;border-radius:50%;background:#8ca178}.is-connected .ma-status-dot,.ma-account .ma-status-dot,.ma-auth-waiting .ma-status-dot{background:#6a9978;box-shadow:0 0 0 3px #6a997814}
